const pool = new Pool({ connectionString: process.env.DB_URL });

export const handler = async (event) => {
  const r = await pool.query("SELECT * FROM produits WHERE id = $1", [event.id]);
  return r.rows[0];
};

export const handler = async (event) => {
  const echecs = [];
  for (const msg of event.Records) {
    try { await traiter(JSON.parse(msg.body)); }
    catch { echecs.push({ itemIdentifier: msg.messageId }); }
  }
  return { batchItemFailures: echecs };
};

